import assert from 'node:assert/strict';
import {createGardenState,stepGarden,restoreGardenState} from '../../../../src/js/garden/GardenSimulation.js';
import {gardenPlatforms} from '../../../../src/js/garden/GardenLevel.js';
export function gardenPilot(s){
 const p=s.player,support=gardenPlatforms(s.time).find(v=>v.id===p.support);
 const edge=support&&support.x+support.w-p.x<95;
 const enemy=s.enemies.some(e=>e.alive&&e.x>p.x&&e.x-p.x<150&&Math.abs(e.y-p.y)<65);
 const jump=p.onGround?(edge||enemy)&&!s.jumpHeld:s.jumpHeld&&p.vy<-100;
 return {x:1,jump};
}
const reports=[];
for(const difficulty of ['NORMAL','EASY'])for(const dt of [1/120,1/60,.02]){
 let s=createGardenState(difficulty),steps=0,falls=0,hits=0,jumps=0;const supports=new Set();
 while(!['COMPLETE','GAME_OVER'].includes(s.stage)&&steps++<18000){const events=stepGarden(s,gardenPilot(s),dt,difficulty);for(const e of events){falls+=e.type==='fall';hits+=e.type==='hurt';jumps+=e.type==='jump';}if(s.player.support)supports.add(s.player.support);if(steps===1000)s=restoreGardenState(JSON.parse(JSON.stringify(s)),difficulty);}
 reports.push({difficulty,dt,stage:s.stage,x:s.player.x,hp:s.hp,falls,hits,jumps,defeated:s.defeated,supports:[...supports]});
}
console.log(JSON.stringify(reports,null,2));assert.ok(reports.every(r=>r.stage==='COMPLETE'),'Percurso inteiro deve ser atravessável com controles normais');assert.ok(reports.every(r=>r.falls===0),'Nenhum vão exige queda ou teletransporte');
console.log('APROVADO: travessia integral com andar/pular, dt variável, apoios reais e save no meio do percurso.');
